L["Summary"] = "Résumé"
-- en: "Syntax checked. No custom code was executed."
L["Syntax checked. No custom code was executed."] = "Syntaxe vérifiée. Aucun code personnalisé n'a été exécuté."
-- en: "The custom condition changed elsewhere. Reopen it before saving."
L["The custom condition changed elsewhere. Reopen it before saving."] = "La condition personnalisée a été modifiée ailleurs. Rouvrez-la avant d'enregistrer."
-- en: "Trusted code"
L["Trusted code"] = "Code de confiance"
-- en: "Validate"
L["Validate"] = "Valider"
-- en: "All tags"
L["All tags"] = "Toutes les étiquettes"
-- en: "Edit the description, tags, author, realm, email, website and version. Source citations remain separate from your attribution. Use changes updates the rotation draft; Apply the rotation to save it. Cancel or Escape restores this dialog’s opening values."
L["Edit the description, tags, author, realm, email, website and version. Source citations remain separate from your attribution. Use changes updates the rotation draft; Apply the rotation to save it. Cancel or Escape restores this dialog’s opening values."] = "Modifiez la description, les étiquettes, l'auteur, le royaume, l'e-mail, le site web et la version. Les citations de sources restent séparées de votre attribution. Utiliser les modifications met à jour le brouillon de la rotation ; appliquez la rotation pour l'enregistrer. Annuler ou Échap rétablit les valeurs d'ouverture de cette fenêtre."
-- en: "Invalid tags. Use up to 64 tags of 64 characters, separated by commas."
L["Invalid tags. Use up to 64 tags of 64 characters, separated by commas."] = "Étiquettes invalides. Utilisez au plus 64 étiquettes de 64 caractères, séparées par des virgules."
-- en: "Separate tags with commas. Use quotes for tags containing commas. Any personal label is allowed."
L["Separate tags with commas. Use quotes for tags containing commas. Any personal label is allowed."] = "Séparez les étiquettes par des virgules. Utilisez des guillemets pour les étiquettes contenant des virgules. Tout libellé personnel est autorisé."
-- en: "Tags"
L["Tags"] = "Étiquettes"
-- en: "Switch priority"
L["Switch priority"] = "Priorité de bascule"
-- en: "Priority %d"
L["Priority %d"] = "Priorité %d"
-- en: "Invalid priority"
L["Invalid priority"] = "Priorité invalide"
-- en: "Switch priority must be a whole number between -100000 and 100000."
L["Switch priority must be a whole number between -100000 and 100000."] = "La priorité de bascule doit être un nombre entier compris entre -100000 et 100000."
-- en: "Edit the description, tags, switch priority, author, realm, email, website and version. Source citations remain separate from your attribution. Use changes updates the rotation draft; Apply the rotation to save it. Cancel or Escape restores this dialog’s opening values."
L["Edit the description, tags, switch priority, author, realm, email, website and version. Source citations remain separate from your attribution. Use changes updates the rotation draft; Apply the rotation to save it. Cancel or Escape restores this dialog’s opening values."] = "Modifiez la description, les étiquettes, la priorité de bascule, l'auteur, le royaume, l'e-mail, le site web et la version. Les citations de sources restent séparées de votre attribution. Utiliser les modifications met à jour le brouillon de la rotation ; appliquez la rotation pour l'enregistrer. Annuler ou Échap rétablit les valeurs d'ouverture de cette fenêtre."
-- en: "Higher priority wins within custom or Built In rotations. Custom rotations and a valid saved fallback take precedence over Built In rotations. Equal priorities use name, then identity. Blank means zero."
L["Higher priority wins within custom or Built In rotations. Custom rotations and a valid saved fallback take precedence over Built In rotations. Equal priorities use name, then identity. Blank means zero."] = "La priorité la plus élevée l'emporte parmi les rotations personnalisées ou Intégrées. Les rotations personnalisées et une rotation de repli enregistrée valide ont la préséance sur les rotations Intégrées. À priorité égale, le nom puis l'identité départagent. Vide signifie zéro."
-- en: "Invalid switch priority for %s:%s; explicit repair resets it to zero."
L["Invalid switch priority for %s:%s; explicit repair resets it to zero."] = "Priorité de bascule invalide pour %s:%s ; une réparation explicite la remet à zéro."
-- en: "Match all ranks"
L["Match all ranks"] = "Correspondre à tous les rangs"
-- en: "%s (any rank)"
L["%s (any rank)"] = "%s (tout rang)"
-- en: "For a numeric spell selection, also recognize auras with the same readable localized spell name. Exact IDs remain the default. Spell names already match by name. Unavailable metadata or restricted aura identity stays unavailable, including under NOT. Different spells sharing a name can match; use exact IDs when that distinction matters."
L["For a numeric spell selection, also recognize auras with the same readable localized spell name. Exact IDs remain the default. Spell names already match by name. Unavailable metadata or restricted aura identity stays unavailable, including under NOT. Different spells sharing a name can match; use exact IDs when that distinction matters."] = "Pour un sort sélectionné par identifiant numérique, reconnaître aussi les auras portant le même nom de sort localisé lisible. Les ID exacts restent le comportement par défaut. Les noms de sort correspondent déjà par nom. Des métadonnées indisponibles ou une identité d'aura restreinte restent indisponibles, y compris sous NOT. Des sorts différents partageant un nom peuvent correspondre ; utilisez les ID exacts lorsque cette distinction compte."
-- en: "Talent tree %s"
L["Talent tree %s"] = "Arbre de talents %s"
-- en: "This client does not expose a Classic talent-tree layout. The saved tree reference is preserved."
L["This client does not expose a Classic talent-tree layout. The saved tree reference is preserved."] = "Ce client n'expose pas de disposition d'arbre de talents Classic. La référence d'arbre enregistrée est conservée."
-- en: "Talent tree"
L["Talent tree"] = "Arbre de talents"
-- en: "Talent Tree Points"
L["Talent Tree Points"] = "Points d'arbre de talents"
-- en: "points spent in %s"
L["points spent in %s"] = "points dépensés dans %s"
-- en: "Talent tree selects the Classic tree whose spent points are compared. Public points are read again on the next evaluation; missing or restricted points are unavailable, including under NOT. Grids and trait trees are unsupported."
L["Talent tree selects the Classic tree whose spent points are compared. Public points are read again on the next evaluation; missing or restricted points are unavailable, including under NOT. Grids and trait trees are unsupported."] = "Arbre de talents sélectionne l'arbre Classic dont les points dépensés sont comparés. Les points publics sont relus à l'évaluation suivante ; les points manquants ou restreints sont indisponibles, y compris sous NOT. Les grilles et les arbres de traits ne sont pas pris en charge."
-- en: "Compare whole points spent from zero to 512. An explicit comparison with zero can describe an unspent tree."
L["Compare whole points spent from zero to 512. An explicit comparison with zero can describe an unspent tree."] = "Comparez le nombre entier de points dépensés, de zéro à 512. Une comparaison explicite avec zéro peut décrire un arbre sans point dépensé."
-- en: "Primary Talent Tree"
L["Primary Talent Tree"] = "Arbre de talents principal"
-- en: "your primary talent tree is %s"
L["your primary talent tree is %s"] = "votre arbre de talents principal est %s"
-- en: "Talent tree selects the unique Classic tree with the most positive spent points. Equal maxima, no spent points, missing records and restricted points are unavailable, including under NOT."
L["Talent tree selects the unique Classic tree with the most positive spent points. Equal maxima, no spent points, missing records and restricted points are unavailable, including under NOT."] = "Arbre de talents sélectionne l'unique arbre Classic ayant le plus de points dépensés (strictement positifs). Des maxima égaux, l'absence de points dépensés, des enregistrements manquants et des points restreints sont indisponibles, y compris sous NOT."
-- en: "The primary tree is derived from readable points, not the saved rotation slot. Hybrid builds may need tree-point or individual-talent conditions instead; the primary tree does not assign a tank or healer role. Grids and trait trees are unsupported."
L["The primary tree is derived from readable points, not the saved rotation slot. Hybrid builds may need tree-point or individual-talent conditions instead; the primary tree does not assign a tank or healer role. Grids and trait trees are unsupported."] = "L'arbre principal est déduit des points lisibles, pas de l'emplacement de rotation enregistré. Les builds hybrides peuvent nécessiter à la place des conditions sur les points d'arbre ou sur des talents individuels ; l'arbre principal n'attribue pas de rôle de tank ou de soigneur. Les grilles et les arbres de traits ne sont pas pris en charge."
-- en: "Item sets are checked in priority order. Bag counts use the first carried candidate, not the sum. Availability, range and cooldown checks use the first carried or equipped candidate. Missing or restricted observations stay unavailable, including under NOT."
L["Item sets are checked in priority order. Bag counts use the first carried candidate, not the sum. Availability, range and cooldown checks use the first carried or equipped candidate. Missing or restricted observations stay unavailable, including under NOT."] = "Les ensembles d'objets sont vérifiés par ordre de priorité. Le décompte dans les sacs utilise le premier candidat porté, pas la somme. Les vérifications de disponibilité, de portée et de temps de recharge utilisent le premier candidat porté ou équipé. Les observations manquantes ou restreintes restent indisponibles, y compris sous NOT."
-- en: "Item Available checks the required level and enabled item cooldown. An active cooldown qualifies only when it ends with the readable global cooldown. This condition does not bypass the action's implicit ownership, usability and range checks."
L["Item Available checks the required level and enabled item cooldown. An active cooldown qualifies only when it ends with the readable global cooldown. This condition does not bypass the action's implicit ownership, usability and range checks."] = "Objet disponible vérifie le niveau requis et le temps de recharge de l'objet activé. Un temps de recharge actif n'est accepté que s'il se termine avec le temps de recharge global lisible. Cette condition ne contourne pas les vérifications implicites de possession, d'utilisabilité et de portée de l'action."
-- en: "Diagram view"
L["Diagram view"] = "Vue diagramme"
-- en: "List view"
L["List view"] = "Vue liste"
-- en: "Switch between the diagram and compact tree list. This changes only the view."
L["Switch between the diagram and compact tree list. This changes only the view."] = "Basculer entre le diagramme et la liste arborescente compacte. Seule la vue change."
-- en: "Zoom out"
L["Zoom out"] = "Dézoomer"
-- en: "Zoom in"
L["Zoom in"] = "Zoomer"
-- en: "Reset canvas zoom to 100%. Drag empty canvas space to pan. Window scale is unchanged."
L["Reset canvas zoom to 100%. Drag empty canvas space to pan. Window scale is unchanged."] = "Réinitialiser le zoom du canevas à 100%. Faites glisser un espace vide du canevas pour le déplacer. L'échelle de la fenêtre est inchangée."
-- en: "Navigating rotations"
L["Navigating rotations"] = "Naviguer dans les rotations"
-- en: "Diagram / List changes only the rotation view; General settings choose the default. Diagram has floating minus, percentage and plus controls at the bottom right. Scroll to zoom from 25% to 200%; click the percentage or middle-click to reset to 100%. Drag empty diagram space to pan. List uses normal scrollbars with touching cards and boxed branch arms, False before True. Cooldowns use a separate scrolling grid. Dragging cards reorders them in every view. Each workspace currently shows at most 200 cards; the remaining saved cards are preserved."
L["Diagram / List changes only the rotation view; General settings choose the default. Diagram has floating minus, percentage and plus controls at the bottom right. Scroll to zoom from 25% to 200%; click the percentage or middle-click to reset to 100%. Drag empty diagram space to pan. List uses normal scrollbars with touching cards and boxed branch arms, False before True. Cooldowns use a separate scrolling grid. Dragging cards reorders them in every view. Each workspace currently shows at most 200 cards; the remaining saved cards are preserved."] = "Diagramme / Liste ne change que la vue de la rotation ; les paramètres Généraux choisissent la vue par défaut. Le diagramme dispose de contrôles flottants moins, pourcentage et plus en bas à droite. Faites défiler pour zoomer de 25% à 200% ; cliquez sur le pourcentage ou faites un clic milieu pour revenir à 100%. Faites glisser un espace vide du diagramme pour le déplacer. La liste utilise des barres de défilement normales, avec des cartes accolées et des bras de branche encadrés, Faux avant Vrai. Les temps de recharge utilisent une grille défilante séparée. Faire glisser des cartes les réordonne dans toutes les vues. Chaque espace de travail affiche actuellement au plus 200 cartes ; les cartes enregistrées restantes sont conservées."
-- en: "Enabled / Disabled"
L["Enabled / Disabled"] = "Activé / Désactivé"
-- en: "Announcement substitutions"
L["Announcement substitutions"] = "Substitutions d'annonce"
-- en: "New, Duplicate, Import/Export and Compare"
L["New, Duplicate, Import/Export and Compare"] = "Nouveau, Dupliquer, Importer/Exporter et Comparer"
-- en: "Announcement details stay always expanded while editing. Press Enter or leave a text field to stage its value; Apply saves the draft. Invalid fields must be corrected before Apply; Discard abandons pending changes. Searchable selectors open on click and filter as you type. The page Help icon explains every option and text substitution."
L["Help.Announces.editing"] = "Les détails de l'annonce restent toujours développés pendant la modification. Appuyez sur Entrée ou quittez un champ de texte pour préparer sa valeur ; Appliquer enregistre le brouillon. Les champs invalides doivent être corrigés avant Appliquer ; Abandonner renonce aux modifications en attente. Les sélecteurs avec recherche s'ouvrent au clic et filtrent à mesure que vous tapez. L'icône d'aide de la page explique chaque option et chaque substitution de texte."
-- en: "Announce selected spell casts or item uses independently of your active rotation, or invoke a configured Via Script/Macro entry directly. Select an entry in the sidebar, or use New to prepare one. The trigger applies to every ordered output card; each card has its own destination and conditions. These settings do not cast spells or use items. Cast-triggered announcements follow RM's combat-data policy and do not run on reference-only clients."
L["Help.Announces.overview"] = "Annoncez certains lancers de sorts ou utilisations d'objets indépendamment de votre rotation active, ou invoquez directement une entrée Via script/macro configurée. Sélectionnez une entrée dans la barre latérale, ou utilisez Nouveau pour en préparer une. Le déclencheur s'applique à chaque carte de sortie ordonnée ; chaque carte a sa propre destination et ses propres conditions. Ces paramètres ne lancent pas de sorts et n'utilisent pas d'objets. Les annonces déclenchées par un lancer suivent la politique de RM sur les données de combat et ne s'exécutent pas sur les clients en mode référence uniquement."
-- en: "An optional name identifies this announcement in the sidebar. Without one, the action name or Via Script/Macro identifier is used. Changing this display name does not change the watched action or callable identifier."
L["Help.Announces.name"] = "Un nom facultatif identifie cette annonce dans la barre latérale. Sans nom, le nom de l'action ou l'identifiant Via script/macro est utilisé. Changer ce nom d'affichage ne change ni l'action surveillée ni l'identifiant appelable."
-- en: "Choose Spell, Pet Spell, Item or Via Script/Macro. Changing type clears the previous action and exact-rank choice. Via Script/Macro uses an Identifier instead of a cast event or stored action; switching back restores the event selector. Choosing the current type keeps its fields."
L["Help.Announces.type"] = "Choisissez Sort, Sort de familier, Objet ou Via script/macro. Changer de type efface l'action précédente et le choix de rang exact. Via script/macro utilise un Identifiant au lieu d'un événement de lancer ou d'une action enregistrée ; revenir en arrière rétablit le sélecteur d'événement. Choisir le type actuel conserve ses champs."
-- en: "Watch one of your spells. Choose the spell in the searchable field below Action Type."
L["Help.Announces.type.spell"] = "Surveiller l'un de vos sorts. Choisissez le sort dans le champ avec recherche sous Type d'action."
-- en: "Watch a spell from your pet spellbook. The spell selector uses the pet catalog for this action type."
L["Help.Announces.type.pet"] = "Surveiller un sort du grimoire de votre familier. Le sélecteur de sort utilise le catalogue du familier pour ce type d'action."
-- en: "Watch item-use spells from a reusable item set or a custom list. This is an announcement trigger; it does not choose an item to use for you."
L["Help.Announces.type.item"] = "Surveiller les sorts d'utilisation d'objet d'un ensemble d'objets réutilisable ou d'une liste personnalisée. Il s'agit d'un déclencheur d'annonce ; il ne choisit pas pour vous un objet à utiliser."
-- en: "Search by spell name, select a result, or drag a spell from your spellbook or action bar into the field. The icon and name identify the selected spell. Spell and pet spell choices keep their respective catalog scope."
L["Help.Announces.spell"] = "Recherchez par nom de sort, sélectionnez un résultat, ou faites glisser un sort depuis votre grimoire ou votre barre d'action dans le champ. L'icône et le nom identifient le sort sélectionné. Les choix de sort et de sort de familier conservent la portée de leur catalogue respectif."
-- en: "Checked limits matching to the selected rank. Unchecked includes the known ranks in that spell family. This checkbox is shown only for Spell and Pet Spell."
L["Help.Announces.ranked"] = "Coché, limite la correspondance au rang sélectionné. Décoché, inclut les rangs connus de cette famille de sorts. Cette case n'apparaît que pour Sort et Sort de familier."
-- en: "Choose a reusable set, or Custom to edit this announcement's own list. For a custom list, search for or drag items into the fields; Add item appends one and a red trash can removes an entry. Any matching item-use spell in the list can trigger the announcement; list order does not limit announcements to the first carried item. Changes to a shared set belong on the Item Sets page."
L["Help.Announces.items"] = "Choisissez un ensemble réutilisable, ou Personnalisé pour modifier la liste propre à cette annonce. Pour une liste personnalisée, recherchez des objets ou faites-les glisser dans les champs ; Ajouter un objet en ajoute un à la fin et une corbeille rouge retire une entrée. Tout sort d'utilisation d'objet correspondant de la liste peut déclencher l'annonce ; l'ordre de la liste ne limite pas les annonces au premier objet porté. Les modifications d'un ensemble partagé se font sur la page Ensembles d'objets."
-- en: "For automatic action types, choose which observed cast event triggers this entry. A start, stop, interruption, failure or delay is different from a successful cast. Client support determines which events and observations are available. Via Script/Macro has no cast event."
L["Help.Announces.event"] = "Pour les types d'action automatiques, choisissez quel événement de lancer observé déclenche cette entrée. Un début, un arrêt, une interruption, un échec ou un retard diffère d'un lancer réussi. Le client détermine quels événements et observations sont disponibles. Via script/macro n'a pas d'événement de lancer."
-- en: "The cast or channel started. This event does not mean it will finish successfully."
L["Help.Announces.event.START"] = "L'incantation ou la canalisation a commencé. Cet événement ne signifie pas qu'elle se terminera avec succès."
-- en: "The cast or channel stopped. A stop alone does not establish whether it succeeded."
L["Help.Announces.event.STOP"] = "L'incantation ou la canalisation s'est arrêtée. Un arrêt seul n'établit pas si elle a réussi."
-- en: "The client reported a successful spell cast or item-use spell. For a channel, this can occur as channeling begins rather than after its final tick."
L["Help.Announces.event.SUCCEEDED"] = "Le client a signalé un lancer de sort ou un sort d'utilisation d'objet réussi. Pour une canalisation, cela peut se produire au début de la canalisation plutôt qu'après son dernier tick."
-- en: "The client reported that the cast was interrupted. This can include cancelling a cast yourself."
L["Help.Announces.event.INTERRUPTED"] = "Le client a signalé que l'incantation a été interrompue. Cela peut inclure l'annulation d'une incantation par vous-même."
-- en: "The client reported that the cast failed. This is separate from the successful-cast event."
L["Help.Announces.event.FAILED"] = "Le client a signalé que l'incantation a échoué. Cet événement est distinct de l'événement de lancer réussi."
-- en: "The client reported a delay to the cast. This event is not a completion or success notification."
L["Help.Announces.event.DELAYED"] = "Le client a signalé un retard de l'incantation. Cet événement n'est pas une notification d'achèvement ni de réussite."
-- en: "Choose a chat destination, local output, a named Emote or Audible. Emote replaces Text with an emote selector and optional recipient. Audible replaces Text with Sound. Text is retained when switching modes. Say, Yell, Whisper and named joined channels are offered only for Via Script/Macro and remain subject to native restrictions."
L["Help.Announces.announce"] = "Choisissez une destination de discussion, une sortie locale, une Emote nommée ou Sonore. Emote remplace Texte par un sélecteur d'emote et un destinataire facultatif. Sonore remplace Texte par Son. Le texte est conservé lors du changement de mode. Dire, Crier, Chuchoter et les canaux nommés rejoints ne sont proposés que pour Via script/macro et restent soumis aux restrictions natives."
-- en: "Play the selected sound locally on the Master audio channel; no chat message is sent. Choose an available sound before applying the announcement."
L["Help.Announces.channel.audible"] = "Joue le son sélectionné localement sur le canal audio principal ; aucun message de discussion n'est envoyé. Choisissez un son disponible avant d'appliquer l'annonce."
-- en: "Use raid chat while in a raid, party chat while in a party, or your local chat frame while solo."
L["Help.Announces.channel.partyraid"] = "Utilise la discussion de raid en raid, la discussion de groupe en groupe, ou votre fenêtre de discussion locale en solo."
-- en: "Use party chat when grouped, including your party within a raid. This destination produces no solo chat message."
L["Help.Announces.channel.party"] = "Utilise la discussion de groupe lorsque vous êtes groupé, y compris votre groupe au sein d'un raid. Cette destination ne produit aucun message en solo."
-- en: "Request group warning output. Depending on group membership and permissions, RM may use raid chat, party chat, or local output instead."
L["Help.Announces.channel.raidwarn"] = "Demande une sortie en avertissement de groupe. Selon l'appartenance au groupe et les permissions, RM peut utiliser à la place la discussion de raid, la discussion de groupe ou la sortie locale."
-- en: "A saved free-text emote keeps its original message. Select Emote to use a named client emote instead."
L["Help.Announces.channel.emote"] = "Une emote en texte libre enregistrée conserve son message d'origine. Sélectionnez Emote pour utiliser à la place une emote nommée du client."
-- en: "Custom emote"
L["Custom emote"] = "Emote personnalisée"
-- en: "Use spell recipient ({{target}})"
L["Use spell recipient ({{target}})"] = "Utiliser le destinataire du sort ({{target}})"
-- en: "Automatic Say and Yell are unavailable. Choose another announcement destination."
L["Automatic Say and Yell are unavailable. Choose another announcement destination."] = "Dire et Crier automatiques sont indisponibles. Choisissez une autre destination d'annonce."
-- en: "Choose a named emote from this client's slash commands, such as /cheer. This does not send the Text field as a custom emote."
L["Help.Announces.channel.gesture"] = "Choisissez une emote nommée parmi les commandes slash de ce client, comme /cheer. Cela n'envoie pas le champ Texte comme emote personnalisée."
-- en: "Choose the emote to perform when the configured cast event is observed. The client may restrict an emote or require a hardware action; RM does not retry through another output path."
L["Help.Announces.emote"] = "Choisissez l'emote à effectuer lorsque l'événement de lancer configuré est observé. Le client peut restreindre une emote ou exiger une action matérielle ; RM ne réessaie pas par une autre voie de sortie."
-- en: "For cast entries, checked directs the emote to the recipient recorded for this exact cast, including click casting. It does not use your current target or a previous cast's recipient. For Via Script/Macro, checked uses the supplied macro unit. A missing recipient skips targeted output. Unchecked performs the emote without a target."
L["Help.Announces.emote_target"] = "Pour les entrées de lancer, coché dirige l'emote vers le destinataire enregistré pour ce lancer précis, y compris le lancer au clic. Elle n'utilise ni votre cible actuelle ni le destinataire d'un lancer précédent. Pour Via script/macro, coché utilise l'unité de macro fournie. Un destinataire manquant ignore la sortie ciblée. Décoché, l'emote est effectuée sans cible."
-- en: "Write to your own chat frame. Other players do not receive this message."
L["Help.Announces.channel.local"] = "Écrire dans votre propre fenêtre de discussion. Les autres joueurs ne reçoivent pas ce message."
-- en: "Enter the message for a chat destination. The substitutions below insert action and cast information when it is available. This text is not used for Audible or named Emote output."
L["Help.Announces.text"] = "Saisissez le message pour une destination de discussion. Les substitutions ci-dessous insèrent les informations d'action et de lancer lorsqu'elles sont disponibles. Ce texte n'est pas utilisé pour les sorties Sonore ou Emote nommée."
-- en: "For cast entries, {{spell}} is a spell link, {{item}} an item link and {{event}} the localized event name. {{target}} uses the recorded cast target, with the last recorded target for that spell as a fallback; it does not automatically use your selected target or your name. Unavailable cast substitutions can remain unchanged. Via Script/Macro instead uses its supplied target and spell, {{event}} becomes Via Script/Macro, and required missing inputs skip output; this API supplies no {{item}}."
L["Help.Announces.substitutions"] = "Pour les entrées de lancer, {{spell}} est un lien de sort, {{item}} un lien d'objet et {{event}} le nom localisé de l'événement. {{target}} utilise la cible de lancer enregistrée, avec en repli la dernière cible enregistrée pour ce sort ; il n'utilise pas automatiquement votre cible sélectionnée ni votre nom. Les substitutions de lancer indisponibles peuvent rester inchangées. Via script/macro utilise plutôt la cible et le sort fournis, {{event}} devient Via script/macro, et l'absence d'entrées requises annule la sortie ; cette API ne fournit pas de {{item}}."
-- en: "Choose a sound supplied by the shared-media catalog, then click Play to preview it. Preview is local and does not save the draft. An unavailable sound cannot be previewed; Audible announcements require a nonempty sound selection."
L["Help.Announces.sound"] = "Choisissez un son fourni par le catalogue de médias partagés, puis cliquez sur Lire pour l'écouter. L'écoute est locale et n'enregistre pas le brouillon. Un son indisponible ne peut pas être écouté ; les annonces Sonores exigent un son sélectionné."
-- en: "The pill turns this entry on or off while keeping its fields. Disabled entries do not announce matching casts or macro invocations. Apply saves the changed state."
L["Help.Announces.state"] = "La pastille active ou désactive cette entrée tout en conservant ses champs. Les entrées désactivées n'annoncent pas les lancers ou invocations de macro correspondants. Appliquer enregistre le changement d'état."
-- en: "Edits stay in a draft until Apply. Complete the action or Via Script/Macro identifier and other required fields before saving. Discard abandons changes to saved announcements; Cancel closes a new creation draft. Leaving pending changes offers Apply, Discard or Cancel navigation."
L["Help.Announces.save"] = "Les modifications restent dans un brouillon jusqu'à Appliquer. Complétez l'action ou l'identifiant Via script/macro et les autres champs requis avant d'enregistrer. Abandonner renonce aux modifications des annonces enregistrées ; Annuler ferme un brouillon de création. Quitter avec des modifications en attente propose Appliquer, Abandonner ou Annuler la navigation."
-- en: "Use the sidebar buttons to create, duplicate, transfer or compare announcements. Apply saves the imported draft; Compare does not merge entries. Via Script/Macro Duplicate assigns a distinct identifier and every copied output gets a fresh identity. Series exports use version 2; version 1 remains available for legacy single-output entries. Imports and Apply reject ambiguous identifiers. The red trash permanently deletes the selected saved entry after confirmation. Resolve pending edits first; deletion does not carry into the next selected draft."
L["Help.Announces.collections"] = "Utilisez les boutons de la barre latérale pour créer, dupliquer, transférer ou comparer des annonces. Appliquer enregistre le brouillon importé ; Comparer ne fusionne pas les entrées. Dupliquer une entrée Via script/macro attribue un identifiant distinct, et chaque sortie copiée reçoit une nouvelle identité. Les exportations de séries utilisent la version 2 ; la version 1 reste disponible pour les anciennes entrées à sortie unique. Les importations et Appliquer rejettent les identifiants ambigus. La corbeille rouge supprime définitivement l'entrée enregistrée sélectionnée après confirmation. Résolvez d'abord les modifications en attente ; la suppression ne se reporte pas sur le brouillon sélectionné ensuite."
-- en: "Press Enter or leave a text field to stage its value; Apply saves the draft. Invalid text stays red and blocks navigation until corrected. Searchable selectors open on click and filter as you type. Section headings collapse or expand their contents."
L["Press Enter or leave a text field to stage its value; Apply saves the draft. Invalid text stays red and blocks navigation until corrected. Searchable selectors open on click and filter as you type. Section headings collapse or expand their contents."] = "Appuyez sur Entrée ou quittez un champ de texte pour préparer sa valeur ; Appliquer enregistre le brouillon. Un texte invalide reste en rouge et bloque la navigation jusqu'à sa correction. Les sélecteurs avec recherche s'ouvrent au clic et filtrent à mesure que vous tapez. Les titres de section replient ou développent leur contenu."
-- en: "An item set is an ordered list of alternatives, such as different mana potions. Runtime selection checks the list from the top for a carried or, where requested, equipped item. Priority comes from the order you choose, not the item level. Selecting an item does not by itself prove that it is usable, off cooldown, or in range; action readiness is checked separately."
L["Help.ItemSets.overview"] = "Un ensemble d'objets est une liste ordonnée d'alternatives, comme différentes potions de mana. La sélection en jeu parcourt la liste depuis le haut à la recherche d'un objet porté ou, si demandé, équipé. La priorité vient de l'ordre que vous choisissez, pas du niveau d'objet. Sélectionner un objet ne prouve pas à lui seul qu'il est utilisable, hors temps de recharge ou à portée ; la disponibilité de l'action est vérifiée séparément."
-- en: "Name the selected set so it can be found in the sidebar and referenced by rotations or conditions. New opens a name form; its first Apply saves an empty named set. Add items afterward and Apply again to save them. Discarding later item edits keeps that already saved set. Renaming a set does not change its identity in saved references."
L["Help.ItemSets.name"] = "Nommez l'ensemble sélectionné pour le retrouver dans la barre latérale et le référencer dans des rotations ou des conditions. Nouveau ouvre un formulaire de nom ; son premier Appliquer enregistre un ensemble nommé vide. Ajoutez ensuite des objets et appliquez de nouveau pour les enregistrer. Abandonner des modifications d'objets ultérieures conserve l'ensemble déjà enregistré. Renommer un ensemble ne change pas son identité dans les références enregistrées."
-- en: "Checked stores this set in the shared global collection, available to other profiles and characters using this addon database. Unchecked stores it in the current profile, which can itself be shared by characters. This is a staged move; Apply saves it. A profile set takes precedence if a global set has the same saved identity."
L["Help.ItemSets.global"] = "Coché, cet ensemble est stocké dans la collection globale partagée, disponible pour les autres profils et personnages utilisant cette base de données de l'addon. Décoché, il est stocké dans le profil actuel, qui peut lui-même être partagé entre personnages. Ce déplacement est préparé ; Appliquer l'enregistre. Un ensemble de profil a la préséance si un ensemble global a la même identité enregistrée."
-- en: "The list of item cards is the priority order. Put preferred items first. RM can leave a selection unavailable when required inventory or identity observations are missing; it does not treat unknown data as proof that a lower-priority item should be used. The sidebar icon represents the first defined item and need not be the currently carried or highlighted one."
L["Help.ItemSets.items"] = "La liste des cartes d'objets constitue l'ordre de priorité. Placez les objets préférés en premier. RM peut laisser une sélection indisponible lorsque des observations requises d'inventaire ou d'identité manquent ; il ne considère pas des données inconnues comme la preuve qu'un objet de moindre priorité doit être utilisé. L'icône de la barre latérale représente le premier objet défini et n'est pas forcément celui qui est actuellement porté ou en surbrillance."
-- en: "Search by item name and choose a result, or drag an item from your bags or action bar into its field. The icon identifies the item; metadata can take time to load. Edit a row to replace that entry. Use its red trash can to remove it rather than clearing a required item field."
L["Help.ItemSets.item"] = "Recherchez par nom d'objet et choisissez un résultat, ou faites glisser un objet depuis vos sacs ou votre barre d'action dans son champ. L'icône identifie l'objet ; le chargement des métadonnées peut prendre du temps. Modifiez une ligne pour remplacer cette entrée. Utilisez sa corbeille rouge pour la retirer plutôt que de vider un champ d'objet obligatoire."
-- en: "Choose or drag an item into the empty item field above the list, then click Add item to append it to the priority list, or drag Add item into a gap between cards to insert it there. Entering an item in this field alone does not add a row."
L["Help.ItemSets.add"] = "Choisissez ou faites glisser un objet dans le champ d'objet vide au-dessus de la liste, puis cliquez sur Ajouter un objet pour l'ajouter à la fin de la liste de priorités, ou faites glisser Ajouter un objet dans un espace entre les cartes pour l'y insérer. Saisir un objet dans ce champ n'ajoute pas de ligne à lui seul."
-- en: "Move Up / Move Down"
L["Move Up / Move Down"] = "Monter / Descendre"
-- en: "Use the arrows on the left, or drag an item row into a highlighted insertion gap. Ctrl-drag moves that row and all following entries together. The floating preview identifies what you are moving. Moves past the beginning or end are unavailable. Reordering changes priority and stays in the draft until Apply."
L["Help.ItemSets.order"] = "Utilisez les flèches à gauche, ou faites glisser une ligne d'objet dans un espace d'insertion en surbrillance. Ctrl-glisser déplace cette ligne avec toutes les entrées suivantes. L'aperçu flottant indique ce que vous déplacez. Les déplacements au-delà du début ou de la fin sont indisponibles. Réordonner change la priorité et reste dans le brouillon jusqu'à Appliquer."
-- en: "Bind / Unbind"
L["Bind / Unbind"] = "Lier / Délier"
-- en: "Outside combat, apply pending item-set edits before binding. Drag the set (its row in the list, or the Bind pill) onto any action bar slot; an occupied slot swaps, leaving its previous action on the cursor. Or click Bind and then click an empty slot. Both pick up the first available item of the set. RM records the slot and updates it as item availability changes. The pill shows bound slot numbers; click it to unbind and remove still-matching bar items. Replaced bar actions are preserved. Binding changes are immediate action-bar operations, independent of the draft and its history."
L["Help.ItemSets.binding"] = "Hors combat, appliquez les modifications en attente de l'ensemble d'objets avant de le lier. Faites glisser l'ensemble (sa ligne dans la liste, ou la pastille Lier) sur n'importe quel emplacement de barre d'action ; un emplacement occupé est échangé, et son action précédente reste sur le curseur. Ou cliquez sur Lier puis sur un emplacement vide. Les deux méthodes prennent le premier objet disponible de l'ensemble. RM enregistre l'emplacement et le met à jour à mesure que la disponibilité des objets change. La pastille affiche les numéros des emplacements liés ; cliquez dessus pour délier et retirer les objets de barre encore correspondants. Les actions de barre remplacées sont conservées. Les changements de liaison sont des opérations immédiates sur les barres d'action, indépendantes du brouillon et de son historique."
-- en: "Restore the packaged item list for this set. Reset is available only for a set with a packaged default. The restored list is staged until Apply; the name is kept."
L["Help.ItemSets.reset"] = "Restaurer la liste d'objets fournie avec l'addon pour cet ensemble. Réinitialiser n'est disponible que pour un ensemble ayant une valeur par défaut fournie. La liste restaurée est préparée jusqu'à Appliquer ; le nom est conservé."
-- en: "The red trash can at the top right permanently removes the selected saved set after confirmation. Resolve pending edits before the final warning. References in rotations or conditions then need another set. Deletion reconciles still-matching bound bar actions and keeps the set if unbinding fails; the next selection opens without an unsaved deletion marker."
L["Help.ItemSets.delete"] = "La corbeille rouge en haut à droite supprime définitivement l'ensemble enregistré sélectionné après confirmation. Résolvez les modifications en attente avant l'avertissement final. Les références dans les rotations ou les conditions auront alors besoin d'un autre ensemble. La suppression réconcilie les actions de barre liées encore correspondantes et conserve l'ensemble si la déliaison échoue ; la sélection suivante s'ouvre sans marqueur de suppression non enregistrée."
-- en: "Undo / Redo"
L["Undo / Redo"] = "Défaire / Refaire"
-- en: "Undo and Redo travel through recent item-set draft edits, including replacements, additions, ordering and row removals. They are unavailable when that direction has no history. Apply, Discard or leaving the page clears this bounded history. They do not reverse confirmed entity deletion or explicit action-bar binding operations."
L["Help.ItemSets.history"] = "Défaire et Refaire parcourent les modifications récentes du brouillon de l'ensemble d'objets, y compris les remplacements, ajouts, réordonnancements et retraits de lignes. Ils sont indisponibles lorsque cette direction n'a pas d'historique. Appliquer, Abandonner ou quitter la page efface cet historique limité. Ils n'annulent ni une suppression d'entité confirmée ni les opérations explicites de liaison aux barres d'action."
-- en: "Ordinary item-set edits stay in a draft until Apply. Discard restores the saved item sets. Cancel closes a new creation draft. Leaving with pending changes offers Apply, Discard or Cancel navigation. Invalid fields must be corrected before Apply; Discard can abandon them."
L["Help.ItemSets.save"] = "Les modifications ordinaires d'un ensemble d'objets restent dans un brouillon jusqu'à Appliquer. Abandonner rétablit les ensembles d'objets enregistrés. Annuler ferme un brouillon de création. Quitter avec des modifications en attente propose Appliquer, Abandonner ou Annuler la navigation. Les champs invalides doivent être corrigés avant Appliquer ; Abandonner permet d'y renoncer."
-- en: "Use the buttons below the sidebar to create, duplicate, transfer, or compare sets. Duplicate makes an independent profile copy. Import shows the source name and can create a renamed copy or replace the selected list; Apply saves the staged result. Compare inspects differences without merging or modifying either set."
L["Help.ItemSets.collections"] = "Utilisez les boutons sous la barre latérale pour créer, dupliquer, transférer ou comparer des ensembles. Dupliquer crée une copie de profil indépendante. Importer affiche le nom de la source et peut créer une copie renommée ou remplacer la liste sélectionnée ; Appliquer enregistre le résultat préparé. Comparer examine les différences sans fusionner ni modifier aucun des deux ensembles."
-- en: "Legacy macro buttons"
L["Legacy macro buttons"] = "Anciens boutons de macro"
-- en: "Legacy clients may allow /click to invoke an RM item-set button separately from action-bar binding. The name is RM_ followed by the set name with non-alphanumeric characters removed, then an underscore and unit token. For a set named Bandages, an example is /click [@mouseover,nodead,help] RM_Bandages_mouseover. Other unit suffixes include player, pet, target, focus, pettarget, targettarget, focustarget, and mouseovertarget. These buttons contain item-use macro lines and do not provide the same readiness or first-item guarantee as the recommendation engine. Availability is subject to the client's secure-button and macro restrictions; reference-only support does not promise executable macro buttons."
L["Help.ItemSets.macros"] = "Les anciens clients peuvent permettre à /click d'invoquer un bouton d'ensemble d'objets de RM indépendamment de la liaison aux barres d'action. Le nom est RM_ suivi du nom de l'ensemble sans ses caractères non alphanumériques, puis d'un tiret bas et d'un identifiant d'unité. Pour un ensemble nommé Bandages, un exemple est /click [@mouseover,nodead,help] RM_Bandages_mouseover. Les autres suffixes d'unité incluent player, pet, target, focus, pettarget, targettarget, focustarget et mouseovertarget. Ces boutons contiennent des lignes de macro d'utilisation d'objet et n'offrent pas les mêmes garanties de disponibilité ou de premier objet que le moteur de recommandation. Leur disponibilité dépend des restrictions du client sur les boutons sécurisés et les macros ; la prise en charge en mode référence uniquement ne garantit pas de boutons de macro exécutables."
-- en: "Search for an item or drag it into the item field or icon. Choose the result to retain its exact item identity. The icon and name may be unavailable until metadata loads. Field clearing and save behavior belong to the editor that contains this list; use Delete when you intend to remove an entry."
L["Help.ItemSets.list.item"] = "Recherchez un objet ou faites-le glisser dans le champ d'objet ou sur l'icône. Choisissez le résultat pour conserver l'identité exacte de l'objet. L'icône et le nom peuvent être indisponibles jusqu'au chargement des métadonnées. L'effacement des champs et l'enregistrement relèvent de l'éditeur qui contient cette liste ; utilisez Supprimer lorsque vous voulez retirer une entrée."
-- en: "Move this entry to the first position in the item priority list, when that control is offered."
L["Help.ItemSets.list.top"] = "Placer cette entrée en première position de la liste de priorités des objets, lorsque ce contrôle est proposé."
-- en: "Move this entry one position earlier. A move before the first entry is unavailable."
L["Help.ItemSets.list.up"] = "Avancer cette entrée d'une position. Un déplacement avant la première entrée est indisponible."
-- en: "Move this entry one position later. A move past the final entry is unavailable."
L["Help.ItemSets.list.down"] = "Reculer cette entrée d'une position. Un déplacement après la dernière entrée est indisponible."
-- en: "Move this entry to the final position in the item priority list, when that control is offered."
L["Help.ItemSets.list.bottom"] = "Placer cette entrée en dernière position de la liste de priorités des objets, lorsque ce contrôle est proposé."
-- en: "Remove this entry from the list. In a draft editor this remains pending until Apply, and Discard abandons the row edit. Undo is available where the containing editor provides draft history. This differs from permanently deleting the entire set after confirmation."
L["Help.ItemSets.list.delete"] = "Retirer cette entrée de la liste. Dans un éditeur à brouillon, ce retrait reste en attente jusqu'à Appliquer, et Abandonner annule la modification de la ligne. Défaire est disponible lorsque l'éditeur conteneur fournit un historique de brouillon. Cela diffère de la suppression définitive de l'ensemble entier après confirmation."
-- en: "Default rotation view"
L["Default rotation view"] = "Vue de rotation par défaut"
-- en: "Choose Diagram or List as the starting rotation view. This profile preference applies when opening a rotation; changing the view inside the editor does not change this setting. Cooldowns always use a scrolling grid."
L["Choose Diagram or List as the starting rotation view. This profile preference applies when opening a rotation; changing the view inside the editor does not change this setting. Cooldowns always use a scrolling grid."] = "Choisissez Diagramme ou Liste comme vue de rotation initiale. Cette préférence de profil s'applique à l'ouverture d'une rotation ; changer de vue dans l'éditeur ne modifie pas ce paramètre. Les temps de recharge utilisent toujours une grille défilante."
-- en: "Reset diagram zoom to 100%. Scroll to zoom; middle-click to reset. Drag empty space to pan."
L["Reset diagram zoom to 100%. Scroll to zoom; middle-click to reset. Drag empty space to pan."] = "Réinitialiser le zoom du diagramme à 100%. Faites défiler pour zoomer ; clic milieu pour réinitialiser. Faites glisser un espace vide pour déplacer la vue."
-- en: "Move this and following entries"
L["Move this and following entries"] = "Déplacer cette entrée et les suivantes"
-- en: "Drag one entry; Ctrl-drag moves it and all following siblings."
L["Drag one entry; Ctrl-drag moves it and all following siblings."] = "Faites glisser une entrée ; Ctrl-glisser la déplace avec toutes ses sœurs suivantes."
-- en: "%d cards"
L["%d cards"] = "%d cartes"
-- en: " (%d hidden)"
L[" (%d hidden)"] = " (%d masquées)"
-- en: "Click to fold or unfold this branch arm. Other cards and conditions are unchanged."
L["Click to fold or unfold this branch arm. Other cards and conditions are unchanged."] = "Cliquez pour replier ou déplier ce bras de branche. Les autres cartes et conditions restent inchangées."
-- en: "%s totem {{!is|is not}} active"
L["%s totem {{!is|is not}} active"] = "le totem %s {{!est|n'est pas}} actif"
-- en: "%s {{!are|are not}} %s"
L["%s {{!are|are not}} %s"] = "%s {{!êtes|n'êtes pas}} %s"
-- en: "%s {{!are|are not}} PVP flagged"
L["%s {{!are|are not}} PVP flagged"] = "%s {{!avez|n'avez pas}} le JcJ activé"
-- en: "%s {{!are|are not}} a %s"
L["%s {{!are|are not}} a %s"] = "%s {{!êtes|n'êtes pas}} %s"
-- en: "%s {{!are|are not}} currently casting"
L["%s {{!are|are not}} currently casting"] = "%s {{!êtes|n'êtes pas}} en train d'incanter"
-- en: "%s {{!are|are not}} currently casting %s"
L["%s {{!are|are not}} currently casting %s"] = "%s {{!êtes|n'êtes pas}} en train de lancer %s"
-- en: "{unit} {{!are|are not}} currently casting {spell}"
L["{unit} {{!are|are not}} currently casting {spell}"] = "{unit} {{!êtes|n'êtes pas}} en train de lancer {spell}"
-- en: "%s {{!are|are not}} currently channeling"
L["%s {{!are|are not}} currently channeling"] = "%s {{!êtes|n'êtes pas}} en train de canaliser"
-- en: "%s {{!are|are not}} currently channeling %s"
L["%s {{!are|are not}} currently channeling %s"] = "%s {{!êtes|n'êtes pas}} en train de canaliser %s"
-- en: "{unit} {{!are|are not}} currently channeling {spell}"
L["{unit} {{!are|are not}} currently channeling {spell}"] = "{unit} {{!êtes|n'êtes pas}} en train de canaliser {spell}"
-- en: "%s {{!are|are not}} in combat"
L["%s {{!are|are not}} in combat"] = "%s {{!êtes|n'êtes pas}} en combat"
-- en: "%s {{!has|does not have}} %s"
L["%s {{!has|does not have}} %s"] = "%s {{!a|n'a pas}} %s"
-- en: "%s {{!has|does not have}} a %s debuff"
L["%s {{!has|does not have}} a %s debuff"] = "%s {{!a un affaiblissement|n'a aucun affaiblissement}} de type %s"
-- en: "%s {{!has|does not have}} a stealable buff"
L["%s {{!has|does not have}} a stealable buff"] = "%s {{!a une amélioration volable|n'a aucune amélioration volable}}"
